<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ubuntu Desktop</title>
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html,body{width:100%;height:100%;overflow:hidden;font-family:'Segoe UI',Ubuntu,Cantarell,sans-serif;background:#1a1a2e}

/* Desktop */
#desktop{width:100%;height:100%;position:relative;background:linear-gradient(135deg,#1a1a2e 0%,#16213e 40%,#0f3460 100%)}

/* Top Bar */
#top-bar{position:absolute;top:0;left:0;right:0;height:28px;background:rgba(20,20,35,0.95);display:flex;align-items:center;justify-content:space-between;padding:0 16px;z-index:1000;color:#e0e0e0;font-size:13px;user-select:none}
#top-bar .left,#top-bar .right{display:flex;align-items:center;gap:12px}
#top-bar .activity-btn{background:none;border:none;color:#e0e0e0;font-size:13px;cursor:pointer;padding:4px 8px;border-radius:4px}
#top-bar .activity-btn:hover{background:rgba(255,255,255,0.1)}
#clock{font-weight:600;font-size:13px}

/* Taskbar / Dock */
#taskbar{position:absolute;bottom:0;left:50%;transform:translateX(-50%);height:56px;background:rgba(20,20,35,0.92);backdrop-filter:blur(12px);border-radius:12px 12px 0 0;display:flex;align-items:center;padding:0 10px;gap:6px;z-index:999;box-shadow:0 -2px 20px rgba(0,0,0,0.4);border:1px solid rgba(255,255,255,0.08);border-bottom:none}
.dock-btn{width:44px;height:44px;border-radius:10px;border:none;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all 0.15s;position:relative;outline:none}
.dock-btn:hover{background:rgba(255,255,255,0.12);transform:scale(1.08)}
.dock-btn:active{transform:scale(0.95)}
.dock-btn .icon{font-size:24px;line-height:1}
.dock-btn .tooltip{position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);background:rgba(30,30,50,0.95);color:#fff;padding:4px 10px;border-radius:6px;font-size:11px;white-space:nowrap;pointer-events:none;opacity:0;transition:opacity 0.15s;border:1px solid rgba(255,255,255,0.1)}
.dock-btn:hover .tooltip{opacity:1}
.dock-sep{width:1px;height:28px;background:rgba(255,255,255,0.1);margin:0 4px}

/* Windows */
.window{position:absolute;min-width:360px;min-height:240px;background:#1e1e2f;border-radius:10px;box-shadow:0 8px 32px rgba(0,0,0,0.5),0 0 0 1px rgba(255,255,255,0.06);display:flex;flex-direction:column;overflow:hidden;transition:box-shadow 0.2s}
.window.focused{box-shadow:0 12px 48px rgba(0,0,0,0.6),0 0 0 1px rgba(99,132,255,0.25)}
.window-header{height:36px;background:rgba(30,30,48,0.98);display:flex;align-items:center;padding:0 12px;gap:8px;flex-shrink:0;user-select:none;cursor:default;border-bottom:1px solid rgba(255,255,255,0.05)}
.window-header .win-title{flex:1;font-size:13px;font-weight:600;color:#d0d0e0;text-align:center;pointer-events:none}
.window-controls{display:flex;gap:6px;align-items:center}
.window-controls button{width:18px;height:18px;border-radius:50%;border:none;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:10px;color:rgba(255,255,255,0.7);transition:all 0.1s}
.win-close{background:#e05555}
.win-close:hover{background:#ff6b6b;color:#fff}
.win-minimize{background:#555570}
.win-minimize:hover{background:#7777aa;color:#fff}
.window-body{flex:1;overflow:auto;color:#d0d0e0;font-size:13px}

/* Files App */
#files-window{width:620px;height:420px}
.files-toolbar{display:flex;align-items:center;gap:8px;padding:8px 12px;background:rgba(25,25,42,0.95);border-bottom:1px solid rgba(255,255,255,0.05)}
#files-up{background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.1);color:#d0d0e0;padding:5px 10px;border-radius:6px;cursor:pointer;font-size:13px;transition:background 0.1s}
#files-up:hover{background:rgba(255,255,255,0.15)}
#files-up:disabled{opacity:0.3;cursor:default}
#files-path{flex:1;background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.08);color:#b0b0cc;padding:5px 10px;border-radius:6px;font-size:12px;font-family:'Cascadia Code','Fira Code',monospace;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.files-content{padding:8px 12px;display:flex;flex-wrap:wrap;gap:6px;align-content:flex-start}
.fs-item{display:flex;flex-direction:column;align-items:center;gap:4px;padding:10px 14px;border-radius:8px;cursor:pointer;transition:background 0.1s;min-width:80px;text-align:center;user-select:none}
.fs-item:hover{background:rgba(255,255,255,0.07)}
.fs-item .fs-icon{font-size:32px;line-height:1}
.fs-item .fs-name{font-size:11px;color:#c0c0d8;word-break:break-all;line-height:1.3}
.fs-item.folder .fs-icon{filter:drop-shadow(0 0 4px rgba(99,132,255,0.3))}

/* Notepad App */
#notepad-window{width:640px;height:440px}
.notepad-toolbar{display:flex;align-items:center;padding:6px 10px;gap:6px;background:rgba(25,25,42,0.95);border-bottom:1px solid rgba(255,255,255,0.05)}
#new-tab{background:rgba(99,132,255,0.2);border:1px solid rgba(99,132,255,0.3);color:#8fa4ff;padding:4px 12px;border-radius:6px;cursor:pointer;font-size:12px;transition:all 0.15s}
#new-tab:hover{background:rgba(99,132,255,0.35)}
#tabs{display:flex;background:rgba(20,20,35,0.9);border-bottom:1px solid rgba(255,255,255,0.05);overflow-x:auto;flex-shrink:0;min-height:32px}
.tab{display:flex;align-items:center;gap:6px;padding:6px 14px;font-size:12px;color:#9090aa;cursor:pointer;border-right:1px solid rgba(255,255,255,0.05);white-space:nowrap;transition:all 0.1s;position:relative;user-select:none}
.tab:hover{color:#c0c0d8;background:rgba(255,255,255,0.04)}
.tab.active{color:#e0e0f0;background:rgba(99,132,255,0.1);border-bottom:2px solid #6384ff}
.tab .tab-close{font-size:14px;opacity:0.4;transition:opacity 0.1s;line-height:1}
.tab .tab-close:hover{opacity:1;color:#ff6b6b}
#editor{flex:1;width:100%;background:#1a1a28;color:#d0d0e0;border:none;outline:none;resize:none;padding:12px;font-family:'Cascadia Code','Fira Code','Consolas',monospace;font-size:13px;line-height:1.6;tab-size:4}
#editor::placeholder{color:rgba(208,208,232,0.3)}

/* Scrollbar */
::-webkit-scrollbar{width:8px;height:8px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:rgba(255,255,255,0.1);border-radius:4px}
::-webkit-scrollbar-thumb:hover{background:rgba(255,255,255,0.2)}

/* Animations */
@keyframes winOpen{from{opacity:0;transform:scale(0.95)}to{opacity:1;transform:scale(1)}}
.window-opening{animation:winOpen 0.2s ease-out}
</style>
</head>
<body>

<div id="desktop">
  <div id="top-bar">
    <div class="left">
      <button class="activity-btn">Activities</button>
    </div>
    <div style="font-weight:600;font-size:13px;color:#d0d0e0">Ubuntu</div>
    <div class="right">
      <span id="clock"></span>
    </div>
  </div>

  <!-- Taskbar / Dock -->
  <div id="taskbar">
    <button class="dock-btn" id="open-files" title="Files">
      <span class="icon">📁</span>
      <span class="tooltip">Files</span>
    </button>
    <button class="dock-btn" id="open-notepad" title="Notepad">
      <span class="icon">📝</span>
      <span class="tooltip">Notepad</span>
    </button>
    <div class="dock-sep"></div>
    <button class="dock-btn" title="Terminal">
      <span class="icon">⌨️</span>
      <span class="tooltip">Terminal</span>
    </button>
    <button class="dock-btn" title="Settings">
      <span class="icon">⚙️</span>
      <span class="tooltip">Settings</span>
    </button>
  </div>

  <!-- Files Window -->
  <div id="files-window" class="window" style="display:none;left:80px;top:50px">
    <div class="window-header">
      <div class="window-controls">
        <button class="win-close" data-target="files-window" title="Close">✕</button>
      </div>
      <span class="win-title">📁 Files</span>
      <div style="width:18px"></div>
    </div>
    <div class="window-body" style="display:flex;flex-direction:column">
      <div class="files-toolbar">
        <button id="files-up" title="Go to parent folder">⬆ Up</button>
        <div id="files-path">/</div>
      </div>
      <div id="files-content" class="files-content"></div>
    </div>
  </div>

  <!-- Notepad Window -->
  <div id="notepad-window" class="window" style="display:none;left:120px;top:80px">
    <div class="window-header">
      <div class="window-controls">
        <button class="win-close" data-target="notepad-window" title="Close">✕</button>
      </div>
      <span class="win-title">📝 Notepad</span>
      <div style="width:18px"></div>
    </div>
    <div class="window-body" style="display:flex;flex-direction:column">
      <div class="notepad-toolbar">
        <button id="new-tab">+ New Tab</button>
      </div>
      <div id="tabs"></div>
      <textarea id="editor" placeholder="Start typing..."></textarea>
    </div>
  </div>
</div>

<script>
(function(){
  // ─── Clock ───
  function updateClock(){
    const d=new Date();
    document.getElementById('clock').textContent=d.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})+'  '+d.toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'});
  }
  updateClock();setInterval(updateClock,30000);

  // ─── Window Management ───
  let windowZ=100;
  document.querySelectorAll('.window').forEach(w=>{
    w.addEventListener('mousedown',function(){
      windowZ++;
      document.querySelectorAll('.window').forEach(x=>x.classList.remove('focused'));
      this.style.zIndex=windowZ;
      this.classList.add('focused');
    });
  });

  // Close buttons
  document.querySelectorAll('.win-close').forEach(btn=>{
    btn.addEventListener('click',function(){
      const target=this.getAttribute('data-target');
      document.getElementById(target).style.display='none';
    });
  });

  // Open buttons
  document.getElementById('open-files').addEventListener('click',function(){
    const w=document.getElementById('files-window');
    w.style.display='flex';
    w.classList.add('window-opening');
    setTimeout(()=>w.classList.remove('window-opening'),200);
    windowZ++;w.style.zIndex=windowZ;
    document.querySelectorAll('.window').forEach(x=>x.classList.remove('focused'));
    w.classList.add('focused');
  });

  document.getElementById('open-notepad').addEventListener('click',function(){
    const w=document.getElementById('notepad-window');
    w.style.display='flex';
    w.classList.add('window-opening');
    setTimeout(()=>w.classList.remove('window-opening'),200);
    windowZ++;w.style.zIndex=windowZ;
    document.querySelectorAll('.window').forEach(x=>x.classList.remove('focused'));
    w.classList.add('focused');
  });

  // ─── Dragging ───
  document.querySelectorAll('.window').forEach(win=>{
    const hdr=win.querySelector('.window-header');
    let dragging=false,offX,offY;
    hdr.addEventListener('mousedown',function(e){
      if(e.target.closest('.window-controls'))return;
      dragging=true;
      offX=e.clientX-win.offsetLeft;
      offY=e.clientY-win.offsetTop;
      win.style.transition='none';
    });
    document.addEventListener('mousemove',function(e){
      if(!dragging)return;
      win.style.left=Math.max(0,e.clientX-offX)+'px';
      win.style.top=Math.max(0,e.clientY-offY)+'px';
    });
    document.addEventListener('mouseup',function(){
      if(dragging){dragging=false;win.style.transition='';}
    });
  });

  // ─── Filesystem ───
  const FS={
    '/':{type:'folder',children:['bin','etc','home','usr','var']},
    '/bin':{type:'folder',children:['ls','cat','echo','grep','bash']},
    '/bin/ls':{type:'file',ext:''},
    '/bin/cat':{type:'file',ext:''},
    '/bin/echo':{type:'file',ext:''},
    '/bin/grep':{type:'file',ext:''},
    '/bin/bash':{type:'file',ext:''},
    '/etc':{type:'folder',children:['passwd','hosts','apt']},
    '/etc/passwd':{type:'file',ext:'txt'},
    '/etc/hosts':{type:'file',ext:'txt'},
    '/etc/apt':{type:'folder',children:['sources.list']},
    '/etc/apt/sources.list':{type:'file',ext:'txt'},
    '/home':{type:'folder',children:['user']},
    '/home/user':{type:'folder',children:['Documents','Downloads','Pictures','.bashrc','notes.txt']},
    '/home/user/Documents':{type:'folder',children:['resume.pdf','project.md','todo.txt']},
    '/home/user/Documents/resume.pdf':{type:'file',ext:'pdf'},
    '/home/user/Documents/project.md':{type:'file',ext:'md'},
    '/home/user/Documents/todo.txt':{type:'file',ext:'txt'},
    '/home/user/Downloads':{type:'folder',children:['image.png','archive.tar.gz']},
    '/home/user/Downloads/image.png':{type:'file',ext:'png'},
    '/home/user/Downloads/archive.tar.gz':{type:'file',ext:'gz'},
    '/home/user/Pictures':{type:'folder',children:['wallpaper.jpg','photo.png','screenshot.png']},
    '/home/user/Pictures/wallpaper.jpg':{type:'file',ext:'jpg'},
    '/home/user/Pictures/photo.png':{type:'file',ext:'png'},
    '/home/user/Pictures/screenshot.png':{type:'file',ext:'png'},
    '/home/user/.bashrc':{type:'file',ext:'txt'},
    '/home/user/notes.txt':{type:'file',ext:'txt'},
    '/usr':{type:'folder',children:['bin','lib','share']},
    '/usr/bin':{type:'folder',children:['python3','node','npm']},
    '/usr/bin/python3':{type:'file',ext:''},
    '/usr/bin/node':{type:'file',ext:''},
    '/usr/bin/npm':{type:'file',ext:''},
    '/usr/lib':{type:'folder',children:['python3','node']},
    '/usr/lib/python3':{type:'folder',children:[]},
    '/usr/lib/node':{type:'folder',children:[]},
    '/usr/share':{type:'folder',children:['doc','locale']},
    '/usr/share/doc':{type:'folder',children:[]},
    '/usr/share/locale':{type:'folder',children:[]},
    '/var':{type:'folder',children:['log','cache','lib']},
    '/var/log':{type:'folder',children:['syslog','auth.log']},
    '/var/log/syslog':{type:'file',ext:'log'},
    '/var/log/auth.log':{type:'file',ext:'log'},
    '/var/cache':{type:'folder',children:[]},
    '/var/lib':{type:'folder',children:['dpkg','apt']},
    '/var/lib/dpkg':{type:'folder',children:[]},
    '/var/lib/apt':{type:'folder',children:[]}
  };

  let currentPath='/';

  const fileIcons={
    '':'📄','txt':'📄','md':'📄','pdf':'📕','png':'🖼️','jpg':'🖼️','gz':'📦','log':'📋',
    '':'📄'
  };

  function resolvePath(p){
    return p==='/'?FS['/']:FS[p]||null;
  }

  function renderFiles(){
    const node=resolvePath(currentPath);
    if(!node||node.type!=='folder'){
      document.getElementById('files-content').innerHTML='<p style="padding:20px;color:#888">Not a valid directory.</p>';
      return;
    }
    document.getElementById('files-path').textContent=currentPath;
    const upBtn=document.getElementById('files-up');
    upBtn.disabled=currentPath==='/'||currentPath.length<=1;
    const container=document.getElementById('files-content');
    container.innerHTML='';
    (node.children||[]).forEach(name=>{
      const fullPath=currentPath==='/'?'/'+name:currentPath+'/'+name;
      const entry=FS[fullPath];
      if(!entry)return;
      const item=document.createElement('div');
      item.className='fs-item '+(entry.type==='folder'?'folder':'file');
      const icon=document.createElement('span');
      icon.className='fs-icon';
      if(entry.type==='folder'){
        icon.textContent='📁';
      }else{
        const ext=name.includes('.')?name.split('.').pop().toLowerCase():'';
        icon.textContent=fileIcons[ext]||'📄';
      }
      const label=document.createElement('span');
      label.className='fs-name';
      label.textContent=name;
      item.appendChild(icon);
      item.appendChild(label);
      item.addEventListener('dblclick',function(){
        if(entry.type==='folder'){
          currentPath=fullPath;
          renderFiles();
        }
      });
      container.appendChild(item);
    });
    if(!node.children||node.children.length===0){
      container.innerHTML='<p style="padding:24px;color:#666;text-align:center;width:100%">This folder is empty.</p>';
    }
  }

  document.getElementById('files-up').addEventListener('click',function(){
    if(currentPath==='/')return;
    const parts=currentPath.split('/').filter(Boolean);
    parts.pop();
    currentPath=parts.length==='0'||parts.length===0?'/':'/'+parts.join('/');
    renderFiles();
  });

  renderFiles();

  // ─── Notepad ───
  const STORAGE_KEY='ubuntu_desktop_notepad';

  function loadTabs(){
    try{
      const data=localStorage.getItem(STORAGE_KEY);
      if(data)return JSON.parse(data);
    }catch(e){}
    return [{id:Date.now(),title:'Untitled',content:''}];
  }

  function saveTabs(){
    localStorage.setItem(STORAGE_KEY,JSON.stringify(notepadState.tabs));
  }

  let notepadState={tabs:loadTabs(),activeIdx:0};

  function renderTabs(){
    const tabStrip=document.getElementById('tabs');
    tabStrip.innerHTML='';
    notepadState.tabs.forEach((tab,i)=>{
      const el=document.createElement('div');
      el.className='tab'+(i===notepadState.activeIdx?' active':'');
      el.innerHTML=`<span>${tab.title||'Untitled'}</span>`;
      if(notepadState.tabs.length>1){
        const close=document.createElement('span');
        close.className='tab-close';
        close.textContent='✕';
        close.addEventListener('click',function(e){
          e.stopPropagation();
          removeTab(i);
        });
        el.appendChild(close);
      }
      el.addEventListener('click',function(){
        switchTab(i);
      });
      tabStrip.appendChild(el);
    });
    // Update editor
    const active=notepadState.tabs[notepadState.activeIdx];
    if(active){
      document.getElementById('editor').value=active.content||'';
    }
  }

  function switchTab(idx){
    // Save current
    notepadState.tabs[notepadState.activeIdx].content=document.getElementById('editor').value;
    notepadState.activeIdx=idx;
    saveTabs();
    renderTabs();
  }

  function removeTab(idx){
    // Save current content
    notepadState.tabs[notepadState.activeIdx].content=document.getElementById('editor').value;
    notepadState.tabs.splice(idx,1);
    if(notepadState.tabs.length===0){
      notepadState.tabs.push({id:Date.now(),title:'Untitled',content:''});
    }
    if(notepadState.activeIdx>=notepadState.tabs.length)notepadState.activeIdx=notepadState.tabs.length-1;
    saveTabs();
    renderTabs();
  }

  function addTab(){
    // Save current content
    if(notepadState.tabs.length>0){
      notepadState.tabs[notepadState.activeIdx].content=document.getElementById('editor').value;
    }
    const newTab={id:Date.now(),title:'Untitled',content:''};
    notepadState.tabs.push(newTab);
    notepadState.activeIdx=notepadState.tabs.length-1;
    saveTabs();
    renderTabs();
  }

  document.getElementById('new-tab').addEventListener('click',addTab);

  document.getElementById('editor').addEventListener('input',function(){
    if(notepadState.tabs.length>0){
      notepadState.tabs[notepadState.activeIdx].content=this.value;
      saveTabs();
    }
  });

  // Auto-save title from content
  document.getElementById('editor').addEventListener('input',function(){
    const tab=notepadState.tabs[notepadState.activeIdx];
    if(tab){
      const lines=(tab.content||'').split('\n').filter(l=>l.trim());
      tab.title=lines[0]?lines[0].substring(0,30):'Untitled';
      renderTabs();
    }
  });

  renderTabs();

  // Restore focus to most recently used window
  document.querySelectorAll('.window').forEach(w=>{
    if(w.style.display!=='none'){
      windowZ++;w.style.zIndex=windowZ;w.classList.add('focused');
    }
  });
})();
</script>
</body>
</html>
